function maxSlidingWindow(nums, k) {
    const dq = [];
    const res = [];
    for (let i = 0; i < nums.length; i++) {
        while (dq.length > 0 && dq[0] < i - k + 1) dq.shift();
        while (dq.length > 0 && nums[dq[dq.length-1]] < nums[i]) dq.pop();
        dq.push(i);
        if (i >= k - 1) res.push(nums[dq[0]]);
    }
    return res;
}
